#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include <sstream>
using namespace std;

// “小杨的储蓄”判题程序：argv[1] 为考生可执行文件路径。
// 用例 = PDF 样例 + 边界 + 随机压测；期望值由下方独立模拟算出。
static int totalCases = 0, passedCases = 0;

static vector<long long> expectedJar(int n, int d, const vector<int>& a) {
    vector<long long> jar(n, 0);
    for (int i = 1; i <= d; i++) jar[a[i - 1]] += i;
    return jar;
}

static string joinNums(const vector<long long>& v) {
    ostringstream os;
    for (size_t i = 0; i < v.size(); i++) { if (i) os << ' '; os << v[i]; }
    return os.str();
}

static vector<long long> readNums(const string& s) {
    vector<long long> v;
    istringstream is(s);
    long long x;
    while (is >> x) v.push_back(x);
    return v;
}

static void runCase(const string& exe, const string& tag, const string& input, const string& expect) {
    totalCases++;
    string inF = "gesp_l3a_2023_09_p1_" + tag + ".in";
    string outF = "gesp_l3a_2023_09_p1_" + tag + ".out";
    FILE* f = fopen(inF.c_str(), "w");
    if (!f) { printf("[FAIL] case %s: cannot write input file\n", tag.c_str()); return; }
    fputs(input.c_str(), f);
    fclose(f);
    string cmd = "\"" + exe + "\" < " + inF + " > " + outF + " 2>/dev/null";
    int rc = system(cmd.c_str());
    string out;
    FILE* g = fopen(outF.c_str(), "r");
    if (g) {
        char buf[8192];
        size_t r;
        while ((r = fread(buf, 1, sizeof(buf), g)) > 0) out.append(buf, r);
        fclose(g);
    }
    vector<long long> got = readNums(out), want = readNums(expect);
    bool ok = (rc == 0) && (got.size() == want.size());
    if (ok) { for (size_t i = 0; i < got.size(); i++) if (got[i] != want[i]) { ok = false; break; } }
    if (ok) passedCases++;
    else printf("[FAIL] case %s: rc=%d expect[%s] got[%s]\n", tag.c_str(), rc, expect.c_str(), out.c_str());
}

int main(int argc, char** argv) {
    if (argc < 2) { printf("usage: %s <player-exe>\n", argv[0]); return 1; }
    string exe = argv[1];
    runCase(exe, "s1", "2 3\n0 1 0\n", "4 2");
    runCase(exe, "s2", "3 5\n0 0 0 2 0\n", "11 0 4");
    runCase(exe, "b1", "1 1\n0\n", "1");
    {
        int n = 1000, d = 1000;
        ostringstream is;
        is << n << " " << d << "\n";
        vector<int> a(d, n - 1);
        for (int i = 0; i < d; i++) is << a[i] << (i + 1 < d ? ' ' : '\n');
        runCase(exe, "b2", is.str(), joinNums(expectedJar(n, d, a)));
    }
    {
        int n = 7, d = 1000;
        ostringstream is;
        is << n << " " << d << "\n";
        vector<int> a(d);
        for (int i = 0; i < d; i++) { a[i] = i % n; is << a[i] << (i + 1 < d ? ' ' : '\n'); }
        runCase(exe, "b3", is.str(), joinNums(expectedJar(n, d, a)));
    }
    srand(20230915);
    for (int t = 0; t < 5; t++) {
        int n = 1 + rand() % 1000;
        int d = 1 + rand() % 1000;
        vector<int> a(d);
        ostringstream is;
        is << n << " " << d << "\n";
        for (int i = 0; i < d; i++) { a[i] = rand() % n; is << a[i] << (i + 1 < d ? ' ' : '\n'); }
        ostringstream tag;
        tag << "r" << t;
        runCase(exe, tag.str(), is.str(), joinNums(expectedJar(n, d, a)));
    }
    printf("Results: %d/%d passed\n", passedCases, totalCases);
    return passedCases == totalCases ? 0 : 1;
}

