#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include <sstream>
using namespace std;

// “进制判断”判题程序：argv[1] 为考生可执行文件路径。
// 用例 = PDF 样例 + 边界 + 随机压测；期望值由下方独立实现算出。
static int totalCases = 0, passedCases = 0;

static string expectedLine(const string& s) {
    char mx = '0';
    for (size_t i = 0; i < s.size(); i++) if (s[i] > mx) mx = s[i];
    ostringstream os;
    os << (mx <= '1') << ' ' << (mx <= '7') << ' ' << (mx <= '9') << ' ' << (mx <= 'F');
    return os.str();
}

static string expectedAll(const vector<string>& strs) {
    ostringstream os;
    for (size_t i = 0; i < strs.size(); i++) { if (i) os << '\n'; os << expectedLine(strs[i]); }
    return os.str();
}

static vector<long long> readNums(const string& s) {
    vector<long long> v;
    istringstream is(s);
    long long x;
    while (is >> x) v.push_back(x);
    return v;
}

static void runCase(const string& exe, const string& tag, const string& input, const string& expect) {
    totalCases++;
    string inF = "gesp_l3a_2023_09_p2_" + tag + ".in";
    string outF = "gesp_l3a_2023_09_p2_" + tag + ".out";
    FILE* f = fopen(inF.c_str(), "w");
    if (!f) { printf("[FAIL] case %s: cannot write input file\n", tag.c_str()); return; }
    fputs(input.c_str(), f);
    fclose(f);
    string cmd = "\"" + exe + "\" < " + inF + " > " + outF + " 2>/dev/null";
    int rc = system(cmd.c_str());
    string out;
    FILE* g = fopen(outF.c_str(), "r");
    if (g) {
        char buf[8192];
        size_t r;
        while ((r = fread(buf, 1, sizeof(buf), g)) > 0) out.append(buf, r);
        fclose(g);
    }
    vector<long long> got = readNums(out), want = readNums(expect);
    bool ok = (rc == 0) && (got.size() == want.size());
    if (ok) { for (size_t i = 0; i < got.size(); i++) if (got[i] != want[i]) { ok = false; break; } }
    if (ok) passedCases++;
    else printf("[FAIL] case %s: rc=%d expect[%s] got[%s]\n", tag.c_str(), rc, expect.c_str(), out.c_str());
}

int main(int argc, char** argv) {
    if (argc < 2) { printf("usage: %s <player-exe>\n", argv[0]); return 1; }
    string exe = argv[1];
    {
        vector<string> strs;
        strs.push_back("15A6F"); strs.push_back("1011");
        runCase(exe, "s1", "2\n15A6F\n1011\n", expectedAll(strs));
    }
    {
        vector<string> strs;
        strs.push_back("1234567"); strs.push_back("12345678"); strs.push_back("FF"); strs.push_back("GG");
        runCase(exe, "s2", "4\n1234567\n12345678\nFF\nGG\n", expectedAll(strs));
    }
    {
        vector<string> strs;
        strs.push_back("1");
        runCase(exe, "b1", "1\n1\n", expectedAll(strs));
    }
    {
        vector<string> strs;
        strs.push_back("A");
        runCase(exe, "b2", "1\nA\n", expectedAll(strs));
    }
    {
        vector<string> strs;
        strs.push_back("G");
        runCase(exe, "b3", "1\nG\n", expectedAll(strs));
    }
    {
        vector<string> strs;
        strs.push_back("1010101010"); strs.push_back("FFFFFFFFFF"); strs.push_back("9999999999");
        runCase(exe, "b4", "3\n1010101010\nFFFFFFFFFF\n9999999999\n", expectedAll(strs));
    }
    srand(20230916);
    const string head = "123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    const string rest = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    for (int t = 0; t < 5; t++) {
        int n = 1 + rand() % 500;
        vector<string> strs;
        ostringstream is;
        is << n << "\n";
        for (int i = 0; i < n; i++) {
            int len = 1 + rand() % 10;
            string s(1, head[rand() % (int)head.size()]);
            for (int k = 1; k < len; k++) s += rest[rand() % (int)rest.size()];
            strs.push_back(s);
            is << s << "\n";
        }
        ostringstream tag;
        tag << "r" << t;
        runCase(exe, tag.str(), is.str(), expectedAll(strs));
    }
    printf("Results: %d/%d passed\n", passedCases, totalCases);
    return passedCases == totalCases ? 0 : 1;
}
